def transform(wb):
    ws = wb["result"]
    for row in range(2, 13):
        match = f"MATCH($A{row},'main sheet'!$A$2:$A$12,0)"
        desig = f"INDEX('main sheet'!$E$2:$E$12,{match})"
        cond = f'OR({desig}="Branch Manager",{desig}="Branch Credit Manager")'
        for col in range(2, 5):
            cell = ws.cell(row=row, column=col)
            if col == 2:
                out = desig
            elif col == 3:
                out = f"INDEX('main sheet'!$C$2:$C$12,{match})"
            else:
                out = f"INDEX('main sheet'!$D$2:$D$12,{match})"
            cell.value = f'=IFERROR(IF({cond},{out},"N/A"),"N/A")'
            align = copy(cell.alignment)
            align.horizontal = "left"
            cell.alignment = align
